21: func machineInfoCommand(cliContext *cli.Context) error {
22: 	logLevel := cliContext.String("log-level")
23: 	zapLvl, err := log.ParseLogLevel(logLevel)
24: 	if err != nil {
25: 		return err
26: 	}
27: 	log.Logger = log.CreateLogger(zapLvl, "")
28: 
29: 	log.Logger.Debugw("starting machine-info command")
30: 
31: 	stateFile, err := config.DefaultStateFile()
32: 	if err != nil {
33: 		return fmt.Errorf("failed to get state file: %w", err)
34: 	}
35: 
36: 	// only read the state file if it exists (existing gpuhealth login)
37: 	if _, err := os.Stat(stateFile); err == nil {
38: 		// Check if we have read permission to the state file
39: 		if _, err := os.Open(stateFile); err != nil {
40: 			if os.IsPermission(err) {
41: 				return fmt.Errorf("insufficient permissions to read state file %s. Please run with sudo", stateFile)
42: 			}
43: 			// If it's not a permission error, continue - the sqlite.Open call below will handle other issues
44: 		}
45: 
46: 		dbRW, err := sqlite.Open(stateFile)
47: 		if err != nil {
48: 			return fmt.Errorf("failed to open state file: %w", err)
49: 		}
50: 		defer dbRW.Close()
51: 
52: 		dbRO, err := sqlite.Open(stateFile, sqlite.WithReadOnly(true))
53: 		if err != nil {
54: 			return fmt.Errorf("failed to open state file: %w", err)
55: 		}
56: 		defer dbRO.Close()
57: 
58: 		rootCtx, rootCancel := context.WithTimeout(context.Background(), 3*time.Minute)
59: 		defer rootCancel()
60: 		machineID, err := pkgmetadata.ReadMachineIDWithFallback(rootCtx, dbRW, dbRO)
61: 		if err != nil {
62: 			return err
63: 		}
64: 
65: 		fmt.Printf("GPUhealth machine ID: %q\n\n", machineID)
66: 	}
67: 
68: 	nvmlInstance, err := nvidianvml.New()
69: 	if err != nil {
70: 		return err
71: 	}
72: 
73: 	machineInfo, err := machineinfo.GetMachineInfo(nvmlInstance)
74: 	if err != nil {
75: 		return err
76: 	}
77: 	machineInfo.RenderTable(os.Stdout)
78: 
79: 	pubIP, _ := netutil.PublicIP()
80: 	providerInfo := machineinfo.GetProvider(pubIP)
81: 	if providerInfo == nil {
82: 		fmt.Printf("%s failed to find provider (%v)\n", cmdutil.WarningSign, err)
83: 	} else {
84: 		if providerInfo.PrivateIP == "" {
85: 			if machineInfo != nil && machineInfo.NICInfo != nil {
86: 				for _, iface := range machineInfo.NICInfo.PrivateIPInterfaces {
87: 					if iface.IP == "" {
88: 						continue
89: 					}
90: 					if iface.Addr.IsPrivate() && iface.Addr.Is4() {
91: 						providerInfo.PrivateIP = iface.IP
92: 						break
93: 					}
94: 				}
95: 			}
96: 		}
97: 		fmt.Printf("%s successfully found provider %s\n", cmdutil.CheckMark, providerInfo.Provider)
98: 		providerInfo.RenderTable(os.Stdout)
99: 	}
100: 
101: 	return nil
102: }

